<span class="line"><span style="color:#61AFEF;">OBJECT</span><span style="color:#98C379;"> ENCODING</span><span style="color:#98C379;"> user:1</span><span style="color:#7F848E;font-style:italic;">         # &quot;ziplist&quot;</span></span>
