<span class="line"><span style="color:#E5C07B;">            o</span><span style="color:#ABB2BF;">-&gt;</span><span style="color:#E06C75;">ptr</span><span style="color:#C678DD;"> =</span><span style="color:#ABB2BF;"> zl;</span></span>
