<span class="line"><span style="color:#E5C07B;">    d</span><span style="color:#ABB2BF;">-&gt;</span><span style="color:#E06C75;">rehashidx</span><span style="color:#C678DD;"> =</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">;</span></span>
